{"type": "flow", "title": null, "source_page": 8, "notes": [], "nodes": [{"id": "a", "label": "TOTAL VEHICLES 21.6 MILLION"}, {"id": "b", "label": "x 2"}, {"id": "c", "label": "TOTAL NUMBER OF LICENSE PLATES"}], "edges": [{"from": "a", "to": "c", "label": null}, {"from": "b", "to": "c", "label": null}]}
